/**
 * One metric, on the baseline and on the candidate.
 */
export type Score = {
    baseline?: number | null;
    candidate?: number | null;
    metric: string;
};

/**
 * Which SDK produced an event.
 *
 * Serialised as a plain string with an unknown value passing through: an SDK
 * this backend has never heard of must still be able to publish.
 */
export type Sdk = 'Python' | 'Typescript' | 'Rust' | {
    Other: string;
};

/**
 * One written shard of a staged artifact.
 *
 * The unit of resume and the unit of proof. `digest` is over the shard's
 * plaintext bytes — before any encryption, so an archive that seals its
 * shards and an importer that does not produce comparable references — and it
 * is what [`version_of`] builds the artifact's identity from.
 */
export type ShardRef = {
    /**
     * `sha256` of the shard's plaintext JSONL. What proves a shard was not
     * swapped for another.
     */
    digest: string;
    index: number;
    rows: number;
};

/**
 * Who sent the event. Enough to find the process that produced a bad batch.
 */
export type Source = {
    instance?: string | null;
    sdk: Sdk;
    service: string;
};

/**
 * How the bytes are obtained.
 */
export const SourceAccess = {
    OPEN: 'open',
    REQUEST: 'request',
    ACADEMIC: 'academic'
} as const;

/**
 * How the bytes are obtained.
 */
export type SourceAccess = typeof SourceAccess[keyof typeof SourceAccess];

/**
 * A loaded catalogue: the corpora somebody checked, and where to look for more.
 *
 * Cloneable and cheap to hold. An instance loads one at start-up and every
 * reader shares it — the alternative, re-reading a file per request, would
 * make the answer depend on when it was asked.
 */
export type SourceCatalog = {
    directories?: Array<SourceDirectory>;
    sources?: Array<DatasetSource>;
};

/**
 * A place to go looking, rather than a corpus.
 */
export type SourceDirectory = {
    name: string;
    notes?: string;
    url: string;
};

/**
 * One file a batch was read out of, as the hub described it.
 */
export type SourceFile = {
    /**
     * Whatever the hub published: an LFS `sha256`, a git blob id, an ETag.
     * Never verified here, because these bytes are not the bytes this
     * registry stores — an image is hashed on arrival and *that* digest is
     * its identity.
     */
    digest?: string;
    name: string;
    size_bytes?: number | null;
};

export type SourcePage = {
    directories: Array<SourceDirectory>;
    sources: Array<DatasetSource>;
    /**
     * Rows before the filter, so a caller can tell an empty filter from an
     * empty table.
     */
    total: number;
};

/**
 * What the licence permits, stated conservatively.
 */
export const SourceUsage = {
    COMMERCIAL: 'commercial',
    NON_COMMERCIAL: 'non_commercial',
    UNCLEAR: 'unclear'
} as const;

/**
 * What the licence permits, stated conservatively.
 */
export type SourceUsage = typeof SourceUsage[keyof typeof SourceUsage];

/**
 * Lowercase hex span id
 */
export type SpanId = string;

export const SpanKind = {
    INTERNAL: 'internal',
    SERVER: 'server',
    CLIENT: 'client',
    PRODUCER: 'producer',
    CONSUMER: 'consumer'
} as const;

export type SpanKind = typeof SpanKind[keyof typeof SpanKind];

export const SpanOutcome = { OK: 'ok', ERROR: 'error' } as const;

export type SpanOutcome = typeof SpanOutcome[keyof typeof SpanOutcome];

export type SpanPage = {
    next_cursor?: string | null;
    spans: Array<SpanRow>;
    /**
     * Spans matching the filter, before the page limit.
     */
    total_known: number;
};

/**
 * One span, flattened for a list rather than for a tree.
 */
export type SpanRow = {
    agent_id?: string | null;
    duration_ms: number;
    end: string;
    kind: SpanKind;
    model?: string | null;
    name: string;
    /**
     * The four attributes worth filtering on, lifted out of `attributes` so
     * the panel does not have to walk the list to render a row.
     */
    operation?: string | null;
    parent_span_id?: null | SpanId;
    /**
     * From the map key: a `CompletedSpan` carries no run id of its own.
     */
    run_id: string;
    span_id: SpanId;
    start: string;
    status: SpanStatus;
    step_type?: string | null;
    tool?: string | null;
    trace_id: TraceId;
};

export type SpanStatus = {
    status: 'unset';
} | {
    status: 'ok';
} | {
    message: string;
    status: 'error';
};

/**
 * Which side of the split a family is on.
 */
export const Split = {
    TRAIN: 'train',
    VALIDATION: 'validation',
    TEST: 'test'
} as const;

/**
 * Which side of the split a family is on.
 */
export type Split = typeof Split[keyof typeof Split];

/**
 * How families are dealt out. Percentages, summing to 100.
 */
export type SplitRatios = {
    test: number;
    train: number;
    validation: number;
};

/**
 * What a batch is for, decided once and pinned.
 *
 * Rights, evidence and source sit here rather than on each page because they
 * are properties of the *corpus*: a per-page field would invite a pipeline to
 * derive them from a column, which is the mirror's word laundered through a
 * `withEntry`. This is also the "pinned source" half of "re-running the same
 * pinned source and pipeline yields the same version".
 */
export type StageBatchRequest = {
    description?: string;
    /**
     * Who checked that, where and when. Recorded, never enforced.
     */
    evidence?: RightsEvidence;
    project: string;
    /**
     * What the caller asserts may be done with every image in this batch.
     */
    rights?: UsageRights;
    source?: ImportSource;
};

/**
 * A batch as it sits in the store.
 */
export type StagedBatch = {
    batch_id: string;
    created_at: string;
    created_by?: string;
    description: string;
    /**
     * `sha256(request ‖ every page digest, in order)`, once sealed.
     */
    digest?: string | null;
    evidence: RightsEvidence;
    /**
     * One entry per stored page, in order. The same [`ShardRef`] the
     * conversation export writes, because it is the same thing: an ordered,
     * digested piece of a staged artifact.
     */
    pages: Array<ShardRef>;
    project: string;
    /**
     * What was asked for, hashed. Half of the batch's content address.
     */
    request_digest: string;
    rights: UsageRights;
    rows: number;
    /**
     * True once the batch takes no more rows. Set by queueing a job.
     */
    sealed: boolean;
    /**
     * Pages on which no two rows shared a `group_id`.
     *
     * The family split is the one mistake an import cannot detect afterwards:
     * a `group_id` mapped from the file name gives every image its own
     * family, the test score then measures memorisation, and nothing in the
     * numbers says so. Counted per page rather than over the whole batch
     * because the alternative is a set of every group id a million-row import
     * has seen, held in a manifest — so what this supports is the exact
     * statement "every page of this batch gave each row its own family",
     * which is what a filename mapping produces and what a real one does not.
     */
    singleton_pages: number;
    source: ImportSource;
    updated_at: string;
};

/**
 * What opens a run.
 */
export type StartRunRequest = {
    code?: string;
    /**
     * `project@export-sha256`, ideally.
     */
    dataset: string;
    device?: string;
    framework?: string;
    model: string;
    params?: {
        [key: string]: unknown;
    };
    run_id: string;
    schema_version?: string | null;
    workflow_run_id?: string | null;
};

/**
 * Retrieval, embedding, rerank, guardrail — grouped by kind, then by name.
 *
 * Retrieval latency is the number a slow RAG turn gets debugged against, and
 * it is invisible in the LLM and tool breakdowns.
 */
export type StepBreakdown = {
    calls: number;
    failures: number;
    latency: Percentiles;
    name: string;
    step_type: string;
};

/**
 * A stored image blob and what it is.
 */
export type StoredBlob = {
    bytes: number;
    content_type: string;
    /**
     * False when these exact bytes were already stored.
     */
    created: boolean;
    /**
     * SHA-256 of the bytes, computed here. This is the `image_id`.
     */
    image_id: string;
    /**
     * What to put in `ImageRecord::uri`. See [`BLOB_SCHEME`].
     */
    uri: string;
};

/**
 * The stream a run's events live on.
 *
 * One stream per **run**, not per conversation: a conversation can fan out
 * into several agent runs at once, and partitioning the log by conversation
 * would serialise runs that have no reason to wait for each other.
 */
export type StreamName = {
    stream_id: string;
    stream_type: string;
};

export type SuitePage = {
    suites: Array<SuiteSummary>;
    total: number;
};

/**
 * A suite on a dataset, across every evaluation of it that is retained.
 *
 * The level above a report, and the one MLflow calls an experiment.
 */
export type SuiteSummary = {
    dataset?: string | null;
    evaluations: number;
    failed: number;
    last_evaluation_id: string;
    last_started_at: string;
    last_status: EvaluationStatus;
    /**
     * The newest finished evaluation's metrics, and the change from the one
     * before it. A number with no direction is the thing an evaluation page
     * is usually accused of being.
     */
    latest_metrics: {
        [key: string]: number;
    };
    metric_deltas: {
        [key: string]: number;
    };
    pass_rate?: number | null;
    running: number;
    succeeded: number;
    suite: string;
};

/**
 * A number a request has to look like.
 *
 * The shape is a list rather than a string so a server can check it; `None`
 * in a dimension is "any", which is how a batch axis is written. A runtime
 * that validates against this refuses a wrong request instead of reshaping it
 * into something that predicts confidently and wrongly.
 */
export type TensorSpec = {
    /**
     * For a classifier: what index 0, 1, 2 … mean.
     *
     * On the package rather than in the serving code, because a label order
     * that lives in a deployment is a label order that silently permutes when
     * somebody retrains — every metric stays finite and nothing says so. The
     * same failure `ExportDataset` checks `schema_version` for.
     */
    classes?: Array<string>;
    description?: string;
    /**
     * `float32`, `int64`, `uint8`. Free text, because the vocabulary is the
     * runtime's and an enum here would be one framework's list imposed on
     * every other.
     */
    dtype?: string;
    name: string;
    /**
     * `[null, 3, 224, 224]`. A `null` is a free dimension.
     */
    shape?: Array<number | null>;
};

export type ToolBreakdown = {
    calls: number;
    failures: number;
    latency: Percentiles;
    tool_name: string;
};

/**
 * What a tool handed back.
 *
 * Attached to the turn rather than folded into a `Text` part, because a
 * failure is a training signal and a stringified error is not: an SFT shape
 * wants the successful ones, a preference shape often wants exactly the pairs
 * where one branch failed.
 */
export type ToolResult = {
    call_id: string;
    content: string;
    error?: string;
    name: string;
    ok: boolean;
};

export type Totals = {
    /**
     * Cached as a share of input. The one number that says whether prompt
     * caching is doing anything.
     */
    cache_hit_ratio: number;
    cached_tokens: number;
    failed: number;
    input_tokens: number;
    llm_calls: number;
    output_tokens: number;
    running: number;
    runs: number;
    /**
     * Retrievals, embeddings, reranks, guardrails — everything traced as a
     * step rather than as an LLM or tool call.
     */
    step_calls: number;
    succeeded: number;
    tool_calls: number;
};

/**
 * Lowercase hex trace id
 */
export type TraceId = string;

/**
 * One training run, with everything it accumulated.
 */
export type TrainingRun = {
    best?: null | BestMetric;
    checkpoints?: Array<CheckpointRecord>;
    /**
     * The code that ran. A git revision, usually.
     */
    code?: string;
    /**
     * `project@export-sha256` from the annotation registry. A bare project
     * name is recorded and marks the run irreproducible rather than being
     * refused: a smoke test on an unversioned dataset is a legitimate thing
     * to do, and refusing it would only teach people to lie about it.
     */
    dataset: string;
    device?: string;
    ended_at?: string | null;
    epochs?: Array<EpochRecord>;
    error?: string | null;
    framework?: string;
    /**
     * When this run last wrote anything. The only honest answer to "is it
     * still alive", and the field a reader draws a stall from.
     */
    last_heard_from: string;
    /**
     * The model being trained — a name, not a version. The version is what
     * this run *produces*; see [`crate::model::ModelVersion`].
     */
    model: string;
    params?: {
        [key: string]: unknown;
    };
    profiles?: Array<ProfileRecord>;
    /**
     * Whether this run can be pointed at afterwards and repeated. Decided
     * once, when the run opens, and stored rather than re-derived: a rule
     * computed in three places is a rule three places can disagree about, and
     * the panel is one of them.
     */
    reproducible?: boolean;
    run_id: string;
    /**
     * How many times the sampled series has been halved. The effective
     * interval is the original one times two to this power, and saying so is
     * what stops somebody reading a decimated curve as a complete one.
     */
    sample_decimations?: number;
    samples?: Array<SampleRecord>;
    schema_version?: string | null;
    started_at: string;
    status: TrainingStatus;
    /**
     * Set when the orchestrator launched this run, so it joins the workflow
     * execution it belongs to. See ADR_0012 and ADR_0016.
     */
    workflow_run_id?: string | null;
};

export type TrainingRunPage = {
    runs: Array<TrainingRunSummary>;
    total: number;
};

/**
 * A run as it appears in a list: everything but the curve.
 */
export type TrainingRunSummary = {
    best?: null | BestMetric;
    checkpoints: number;
    dataset: string;
    device?: string;
    duration_ms?: number | null;
    ended_at?: string | null;
    epochs: number;
    error?: string | null;
    framework?: string;
    last_heard_from: string;
    model: string;
    reproducible: boolean;
    run_id: string;
    started_at: string;
    status: TrainingStatus;
    workflow_run_id?: string | null;
};

/**
 * What the consent covers.
 *
 * Separate scopes rather than one "may train" flag, because they are
 * genuinely different permissions and the difference is where the accidents
 * happen: an evaluation set that quietly becomes a training set is the same
 * mistake as a research-licensed corpus in a commercial model, one field over.
 */
export const TrainingScope = {
    TRAIN: 'train',
    EVALUATE: 'evaluate',
    SHARE: 'share'
} as const;

/**
 * What the consent covers.
 *
 * Separate scopes rather than one "may train" flag, because they are
 * genuinely different permissions and the difference is where the accidents
 * happen: an evaluation set that quietly becomes a training set is the same
 * mistake as a research-licensed corpus in a commercial model, one field over.
 */
export type TrainingScope = typeof TrainingScope[keyof typeof TrainingScope];

/**
 * Where a run is.
 *
 * `Running` is the *absence* of an end, not a claim that anything is
 * happening — exactly the rule the projector follows for agent runs. A
 * trainer killed by an OOM and a trainer thinking for twenty minutes look
 * identical from here, so nothing in this crate decides which one it is.
 * [`TrainingRun::last_heard_from`] is what a reader draws the line from.
 */
export const TrainingStatus = {
    RUNNING: 'running',
    SUCCEEDED: 'succeeded',
    FAILED: 'failed',
    CANCELLED: 'cancelled'
} as const;

/**
 * Where a run is.
 *
 * `Running` is the *absence* of an end, not a claim that anything is
 * happening — exactly the rule the projector follows for agent runs. A
 * trainer killed by an OOM and a trainer thinking for twenty minutes look
 * identical from here, so nothing in this crate decides which one it is.
 * [`TrainingRun::last_heard_from`] is what a reader draws the line from.
 */
export type TrainingStatus = typeof TrainingStatus[keyof typeof TrainingStatus];

/**
 * The half that is encrypted.
 *
 * A type of its own rather than two fields on the head, because the split is
 * the security boundary: everything in here is sealed, everything outside it
 * is readable by anyone who may list the archive, and a field that moved
 * across the line by accident would be a leak nobody could see in a diff.
 */
export type TurnContent = {
    parts?: Array<ContentPart>;
    tool_results?: Array<ToolResult>;
};

export type TurnPage = {
    /**
     * Where to resume. Absent at the end of the conversation.
     */
    next_offset?: number | null;
    total: number;
    turns: Array<ArchivedTurn>;
};

/**
 * Who decided, when, and why.
 */
export type TurnReview = {
    decided_at?: string | null;
    note?: string;
    preference?: null | PreferenceLabel;
    reviewer?: string;
    state?: TurnReviewState;
};

/**
 * One reviewer's decision about one turn.
 */
export type TurnReviewRequest = {
    /**
     * What the reviewer saw that the scanner did not — an unsafe answer, a
     * name the rules do not recognise. Appended to the turn's findings rather
     * than replacing them: a scanner finding a human disagreed with is a fact
     * about both of them.
     */
    findings?: Array<HumanFinding>;
    note?: string;
    preference?: null | PreferenceLabel;
    state: TurnReviewState;
};

/**
 * Whether a human has decided about this turn.
 */
export const TurnReviewState = {
    PENDING: 'pending',
    APPROVED: 'approved',
    REJECTED: 'rejected'
} as const;

/**
 * Whether a human has decided about this turn.
 */
export type TurnReviewState = typeof TurnReviewState[keyof typeof TurnReviewState];

/**
 * Whether the content is still there.
 */
export const TurnState = { HELD: 'held', ERASED: 'erased' } as const;

/**
 * Whether the content is still there.
 */
export type TurnState = typeof TurnState[keyof typeof TurnState];

/**
 * What may be done with an image, and therefore with a model trained on it.
 */
export type UsageRights = {
    grant?: string;
    kind: 'owned';
} | {
    kind: 'licensed';
    license: string;
    url?: string | null;
} | {
    kind: 'research_only';
    license: string;
    url?: string | null;
} | {
    kind: 'unknown';
};

/**
 * Where a version came from.
 *
 * The distinction the panel needs to answer "did a person write this, or did
 * an optimiser?" — which is the first question asked about a prompt that is
 * behaving strangely.
 */
export type VersionOrigin = {
    origin: 'authored';
} | {
    algorithm: string;
    optimization_id: string;
    origin: 'optimized';
};

/**
 * Why a corpus was withdrawn, and when.
 *
 * An export is immutable and a withdrawal does not change that: the manifest
 * keeps every count, digest and exclusion it had. What is gone is the rows,
 * because the alternative is a published corpus holding words somebody asked
 * to have deleted — and an erasure that stopped at the archive would be an
 * erasure in name only.
 */
export type Withdrawal = {
    at: string;
    by?: string;
    /**
     * The conversations whose erasure caused this.
     */
    conversations: Array<string>;
};

/**
 * A workflow as the catalog holds it.
 */
export type WorkflowDefinition = {
    declared_at: string;
    edges: Array<WorkflowEdge>;
    executions: number;
    failed: number;
    last_activity_at: string;
    name: string;
    nodes: Array<WorkflowNode>;
    running: number;
    succeeded: number;
    /**
     * Content hash of the declared topology, chosen by the producer.
     *
     * Not interpreted here beyond equality: a changed version replaces the
     * stored shape. It exists so re-declaring on every execution — which is
     * what keeps the catalog alive across retention eviction — costs nothing
     * when the shape has not moved.
     */
    version?: string | null;
    workflow_id: string;
};

/**
 * One declared edge. Direction is `from → to`.
 */
export type WorkflowEdge = {
    from: string;
    label?: string | null;
    to: string;
};

/**
 * One node of a declared graph.
 */
export type WorkflowNode = {
    /**
     * The agent expected to run it, when the graph names one.
     */
    agent?: string | null;
    id: string;
    /**
     * What kind of work it is — `chain`, `retriever`, `agent`, whatever the
     * producer calls it. Free text on purpose: the same reason
     * `data.step_type` is free text, so a new kind is not a backend release.
     */
    kind?: string | null;
    name: string;
};

export type WorkflowPage = {
    next_cursor?: string | null;
    total_known: number;
    workflows: Array<WorkflowDefinition>;
};

